(function() {
    const root = document.querySelector('.sl-continue-learning');
    if (!root) return;
    const playBtn = root.querySelector('.sl-item-play-btn') || root.querySelector('[class*="play"]');
    if (playBtn) {
        playBtn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            const container = playBtn.closest('.position-relative') || playBtn.parentElement;
            const urlEl = root.querySelector('.sl-item-video-url');
            const videoUrl = urlEl ? urlEl.innerText.trim() : 'https://www.youtube.com/embed/dQw4w9WgXcQ';
            if (!container || !videoUrl) return;

            const poster = container.querySelector('img');
            if (poster) poster.style.display = 'none';
            playBtn.style.display = 'none';

            const oldIframe = container.querySelector('iframe');
            if (oldIframe) oldIframe.remove();

            const iframe = document.createElement('iframe');
            iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
            iframe.style.position = 'absolute';
            iframe.style.top = '0';
            iframe.style.left = '0';
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.minHeight = '200px';
            iframe.style.border = 'none';
            iframe.style.zIndex = '10';
            iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
            iframe.setAttribute('allowfullscreen', 'true');
            container.appendChild(iframe);
        });
    }
})();
